  titles.input.addEventListener('change',()=>{if(result)title.input.value=result.titles[Number(titles.input.value)]||result.titles[0];});
  save.addEventListener('click',run(()=>{persist(captureEdits());status.textContent='검토한 게시 자료를 현재 영상 기준으로 저장했어요.';}));
  copy.addEventListener('click',run(async()=>{await copyText(publishingText(captureEdits(),Number(titles.input.value)||0));api.toast('게시용 제목·설명·챕터를 복사했어요.');}));
  textSave.addEventListener('click',run(()=>download(new Blob([publishingText(captureEdits(),Number(titles.input.value)||0)],{type:'text/plain;charset=utf-8'}),`${safeFilename(api.getProject().title)}-게시자료.txt`)));
  bundle.addEventListener('click',run(async()=>{const value=captureEdits(),scope=taskScope(api),seq=++serial,abort=new AbortController();controller=abort;setBusy(true);const job=progress.start('게시 설명과 실제 썸네일 PNG를 ZIP으로 묶고 있어요.');try{await nextPaint();const entries=[{name:'게시자료.txt',data:publishingText(value,Number(titles.input.value)||0)},{name:'게시자료.json',data:JSON.stringify(value,null,2)},{name:'챕터.txt',data:value.chapters.map(chapter=>`${chapterTimestamp(chapter.start)} ${chapter.title}`).join('\n')}];for(const item of canvases)entries.push({name:`썸네일-${item.index+1}.png`,data:await canvasBlob(item.canvas)});const blob=await createDeliveryZip(entries,{signal:abort.signal});if(seq!==serial||!matchesScope(api,scope))return;download(blob,`${safeFilename(api.getProject().title)}-게시자료.zip`);job.finish('게시 자료 ZIP을 만들었어요. 영상은 편집기의 영상 내보내기로 별도 저장하세요.');}catch(cause){if(seq===serial)job.fail(cause.message);throw cause;}finally{if(seq===serial){controller=null;setBusy(false);}}}));
  function stop(message='게시 자료 작업을 취소했어요. 기존 결과는 유지돼요.'){serial++;controller?.abort();controller=null;progress.cancel(message);setBusy(false);}
  cancel.addEventListener('click',()=>stop());window.addEventListener('studio-api-settings-change',()=>{if(busy)stop('API 설정이 바뀌어 게시 자료 작성을 취소했어요.');});
  function render(){const project=api.getProject(),next=JSON.stringify(project.production?.publishing||null);if(owner!==project.id){if(busy)stop('프로젝트가 바뀌어 게시 자료 작성을 취소했어요.');owner=project.id;fingerprint='';thumbSerial++;}if(next!==fingerprint){fingerprint=next;hydrate(project.production?.publishing);}refreshActions();}
  render();return{render,flush(){},onClose(){if(busy)stop();},reset(){stop('');thumbSerial++;owner='';fingerprint='';error.textContent='';progress.clear();render();}};
